<?php

namespace models\decision;

use core\Model;
use Database;
use models\acteurs\Personne;

/**
 * Modèle d'association liant une réunion et un participant (table PARTICIPE).
 *
 * @author  AutoGenerated / POO Refactor
 * @version 1.0
 */
class Participe extends Model
{
    public string $REU_ID;
    public string $PER_ID;

    /**
     * Instancie et hydrate le modèle à partir d'un tableau associatif.
     *
     * @param array<string, mixed> $data
     * @return static
     */
    public static function fromArray(array $data): static
    {
        return (new static())->hydrate($data);
    }

    /**
     * Recherche un enregistrement par sa clé composite (REU_ID, PER_ID).
     *
     * @param string $reu_id
     * @param string $per_id
     * @return static|null
     */
    public static function find(string $reu_id, string $per_id): ?static
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM PARTICIPE WHERE REU_ID = ? AND PER_ID = ? LIMIT 1');
        $stmt->execute([$reu_id, $per_id]);
        $row = $stmt->fetch();

        return $row ? (new static())->hydrate($row) : null;
    }

    /**
     * Récupère tous les enregistrements de la table.
     *
     * @return static[]
     */
    public static function findAll(): array
    {
        $stmt = Database::getInstance()->query('SELECT * FROM PARTICIPE');
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Récupère les instances Participe associées à un objet Reunion.
     *
     * @param Reunion $source
     * @return static[]
     */
    public static function getFromReunion(Reunion $source): array
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM PARTICIPE WHERE REU_ID = ?');
        $stmt->execute([$source->REU_ID]);
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Navigue vers l'objet Reunion parent lié à cet enregistrement.
     *
     * @return Reunion|null
     */
    public function getReunion(): ?Reunion
    {
        if (!isset($this->REU_ID)) {
            return null;
        }
        return Reunion::findById($this->REU_ID);
    }

    /**
     * Récupère les instances Participe associées à un objet Personne.
     *
